Method.Implementation:

 try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
   Do %page.%SetValueById("lblUsername", "User: " _ $USERNAME _ ", Subversion " _ $$$SVNSRCURL )
 } catch err
 {
 }

   Quit $$$OK

try {

		zenPage.getComponentById('lblAccess').setValue('Initializing');
		zenPage.getComponentById('lblAccess').setProperty('hidden', false);

		var res = zenPage.ValidateSubversionUser();

		if(res == 0)

		{
			var pg = zenPage.getComponentById('comboboxFunction').getValue()
			zenPage.getComponentById('lblAccess').setValue(pg);
			if (pg == "srcCtrl")
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.SrcCtrlPage.cls");
			}
			else if (pg == "deploy")
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.Deployment.cls");
			}
			else if (pg == "setting")
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.EditSettingsPage.cls");
			}
			else if (pg == "getRecords")
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.GetRecords.cls");
			}
			else
			{
				zenPage.gotoPage("IHC.ITF.SrcCtrlPkg.ResendMsg.cls");
			}
		}
		else
		{
			zenPage.getComponentById('lblAccess').setValue('ReLogin with your name');
		}


}
catch (ex) {
	zenExceptionHandler(ex,arguments);
}

if(evt.keyCode == 13)
{
	zenPage.validateFields()
}
else
{
	zenPage.getComponentById('lblAccess').setProperty('hidden', true);
}
return true;
